var builder = WebApplication.CreateBuilder(args);

builder.Services.AddRateLimiter(options =>
{
    options.GlobalLimiter = PartitionedRateLimiter.Create<HttpContext, string>(context =>
    {
        var clientId = context.User.FindFirst("sub")?.Value
            ?? context.Connection.RemoteIpAddress?.ToString()
            ?? "anonymous";

        return RateLimitPartition.GetTokenBucketLimiter(clientId, key =>
            new TokenBucketRateLimiterOptions
            {
                TokenLimit = 100,
                QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
                QueueLimit = 10,
                ReplenishmentPeriod = TimeSpan.FromMinutes(1),
                TokensPerPeriod = 100,
                AutoReplenishment = true
            });
    });

    options.OnRejected = async (context, token) =>
    {
        context.HttpContext.Response.StatusCode = StatusCodes.Status429TooManyRequests;
        context.HttpContext.Response.Headers.RetryAfter = context.Lease.TryRetryAfter
            ? context.Lease.RetryAfter.Value.TotalSeconds.ToString()
            : string.Empty;

        await context.HttpContext.Response.WriteAsJsonAsync(
            new { error = "Too many requests. Please retry later." },
            token);
    };
});

var app = builder.Build();
app.UseRateLimiter();
app.MapControllers();
app.Run();

public class LoadSheddingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly double _cpuThreshold = 0.80;
    private readonly double _memoryThreshold = 0.85;

    public async Task InvokeAsync(HttpContext context)
    {
        if (IsOverloaded())
        {
            context.Response.StatusCode = StatusCodes.Status503ServiceUnavailable;
            context.Response.Headers.RetryAfter = "1";
            await context.Response.WriteAsJsonAsync(
                new { error = "Service overloaded. Retry shortly." });
            return;
        }

        await _next(context);
    }

    private bool IsOverloaded()
    {
        var cpu = GetCpuUsage();
        var memory = GetMemoryUsage();
        return cpu > _cpuThreshold || memory > _memoryThreshold;
    }
}
